:root{--i-d1:url(data:image/jpeg;base64,);--i-d2:url(data:image/jpeg;base64,);--u-hero:url(data:image/jpeg;base64,);--u-car:url(data:image/jpeg;base64,);--u-cc:url(data:image/jpeg;base64,);--u-pp:url(data:image/jpeg;base64,);--u-gc:url(data:image/jpeg;base64,);--u-ar:url(data:image/jpeg;base64,);--s0:url(data:image/jpeg;base64,);--s1:url(data:image/jpeg;base64,);--s2:url(data:image/jpeg;base64,);--s3:url(data:image/jpeg;base64,);--s4:url(data:image/jpeg;base64,);--s5:url(data:image/jpeg;base64,);--bg:#060304;--card:#130809;--line:rgba(255,64,72,.18);--mu:#c2aaaa;--bl:#ff2b38;--bl2:#8e0d18;--rd:#ff4b4b;--fd:'Barlow Condensed',Impact,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:#fff;font:400 16px/1.65 Inter,system-ui,sans-serif;-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit;text-decoration:none}button{font:inherit;color:inherit}
.glow{position:fixed;inset:0;pointer-events:none;z-index:0;background:radial-gradient(760px 520px at 88% 8%,rgba(255,43,56,.2),transparent 62%),radial-gradient(640px 480px at 6% 70%,rgba(120,8,18,.25),transparent 62%)}
.nav{position:fixed;z-index:60;top:0;left:0;right:0;padding-top:env(safe-area-inset-top,0px);background:rgba(4,8,16,.86);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-bottom:1px solid var(--line)}
.nav::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--bl),transparent);opacity:.7}
.nin{width:min(1280px,calc(100% - 32px));margin:auto;display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:78px}
.lg{display:block;flex:none;border:0;background:none;padding:0;cursor:pointer}.lg img{height:50px;width:auto;display:block}
.tabs{flex:1;min-width:0;display:flex;gap:6px;justify-content:center;overflow-x:auto;scrollbar-width:none}.tabs::-webkit-scrollbar{display:none}
.tabs button{position:relative;flex:none;min-height:46px;padding:0 20px;background:none;border:0;border-radius:99px;color:var(--mu);font:700 17px var(--fd);letter-spacing:.1em;text-transform:uppercase;cursor:pointer;transition:color .3s,background .3s}
.tabs button.on{color:var(--bl);background:none}.tabs button.on::after{content:none}.tabs button:hover{color:#fff}
.ac{flex:none;display:flex;gap:10px;align-items:center}
.wab{width:46px;height:46px;border-radius:50%;border:1px solid rgba(37,211,102,.6);display:grid;place-items:center;background:rgba(37,211,102,.08)}.wab svg{width:24px;fill:#25d366}
.pg{position:relative;z-index:1;padding-top:112px;animation:pin .7s cubic-bezier(.2,.7,.2,1)}@keyframes pin{from{opacity:0;transform:translateY(22px)}}
.w{position:relative;width:min(1240px,calc(100% - 40px));margin:auto}.sec{padding:92px 0;position:relative}
.pl{display:inline-flex;align-items:center;gap:10px;font:700 14px var(--fd);letter-spacing:.2em;text-transform:uppercase;color:var(--bl);border:1px solid rgba(255,43,56,.45);background:rgba(255,43,56,.08);padding:9px 18px;border-radius:99px;margin-bottom:26px}.pl::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--rd)}
.eb{font:700 15px var(--fd);letter-spacing:.26em;text-transform:uppercase;color:var(--bl);margin:0 0 12px;display:flex;align-items:center;gap:14px}.eb::before{content:"";width:44px;height:2px;background:var(--rd)}
h1,h2,h3{margin:0;font-family:var(--fd);text-transform:uppercase;font-style:italic;font-weight:800;line-height:.95}
h1{font-size:clamp(58px,8.6vw,124px)}h2{font-size:clamp(40px,6vw,82px)}h3{font-size:28px;line-height:1.05}
.bl{background:linear-gradient(100deg,#ffc2c6,var(--bl) 45%,var(--bl2));-webkit-background-clip:text;background-clip:text;color:transparent;padding-right:.06em}
.mu{color:var(--mu)}.lead{font-size:clamp(17px,1.7vw,21px);color:var(--mu);max-width:30em;margin:22px 0 34px}
.b{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:56px;padding:0 34px;border-radius:99px;font:700 19px var(--fd);letter-spacing:.1em;text-transform:uppercase;border:1px solid var(--line);cursor:pointer;background:rgba(255,255,255,.04);transition:transform .3s,box-shadow .3s}
.b:hover{transform:translateY(-3px)}.b.p{background:linear-gradient(135deg,#ff3b47,var(--bl2));border-color:transparent;box-shadow:0 14px 40px -10px rgba(255,43,56,.6)}.b.g svg{width:22px;fill:#25d366}.b.sm{min-height:46px;padding:0 24px;font-size:17px}
.row{display:flex;gap:14px;flex-wrap:wrap}.mid{display:flex;justify-content:center;margin-top:46px}
.rv{opacity:0;transform:translateY(40px);transition:opacity .9s cubic-bezier(.2,.7,.2,1),transform .9s cubic-bezier(.2,.7,.2,1)}.rv.in{opacity:1;transform:none}
.pop{animation:pin .6s cubic-bezier(.2,.7,.2,1) both}
.hsec{position:relative;overflow:hidden}.hsec::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 46px,rgba(255,43,56,.05) 46px 48px);-webkit-mask-image:linear-gradient(90deg,transparent 35%,#000);mask-image:linear-gradient(90deg,transparent 35%,#000)}
.hero{display:grid;grid-template-columns:1fr 1.12fr;gap:40px;align-items:center;min-height:calc(100svh - 112px);padding:20px 0 50px}
.hs{display:flex;gap:34px;margin-top:40px;flex-wrap:wrap}.hs b{display:block;font:800 40px/1 var(--fd);font-style:italic;color:var(--bl)}.hs span{font:700 13px var(--fd);letter-spacing:.2em;text-transform:uppercase;color:var(--mu)}
.hv{position:relative}.hv::before{content:"";position:absolute;inset:-6%;background:radial-gradient(closest-side,rgba(255,43,56,.3),transparent);z-index:-1}
.vf{position:relative;aspect-ratio:16/10;border-radius:28px;overflow:hidden;border:1px solid rgba(255,43,56,.4);background:#030814;box-shadow:0 30px 80px -20px rgba(24,115,230,.55)}
.vf>svg{position:absolute;inset:0;width:100%;height:100%;display:block}.vf video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.vf .cap{position:absolute;left:22px;top:18px;display:flex;gap:8px;align-items:center;font:700 14px var(--fd);letter-spacing:.2em;text-transform:uppercase;background:rgba(3,8,20,.7);padding:7px 14px;border-radius:99px}.vf .cap::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--rd);animation:bl 1.2s infinite}@keyframes bl{50%{opacity:.2}}
.vf .tag{position:absolute;right:20px;bottom:18px;font:700 12px var(--fd);letter-spacing:.24em;border:1px solid rgba(255,255,255,.3);border-radius:99px;padding:6px 14px;background:rgba(0,0,0,.4)}
.pbar{position:absolute;left:0;right:0;bottom:0;height:4px;background:rgba(255,255,255,.18)}.pbar i{display:block;height:100%;background:linear-gradient(90deg,var(--bl),var(--rd));animation:pb 9s linear infinite}@keyframes pb{from{width:0}to{width:100%}}
.rays{animation:ry 6s ease-in-out infinite alternate}@keyframes ry{from{opacity:.35}to{opacity:.9}}
.fm{fill:#fff;transform-box:fill-box;transform-origin:center;opacity:0;animation:fm 9s infinite}@keyframes fm{0%{transform:scale(0);opacity:0}14%{transform:scale(1);opacity:.96}48%{transform:scale(1);opacity:.96}64%{transform:translateY(70px);opacity:0}100%{transform:scale(0);opacity:0}}
.jt{stroke:#bfe8ff;stroke-width:4;stroke-linecap:round;stroke-dasharray:16 20;opacity:0;animation:jt 9s infinite}@keyframes jt{0%,44%{opacity:0;stroke-dashoffset:0}48%{opacity:.95}62%{opacity:.95;stroke-dashoffset:-140}66%,100%{opacity:0}}
.sw{opacity:0;animation:sw 9s infinite}@keyframes sw{0%,66%{opacity:0;transform:translateX(-120px) skewX(-20deg)}72%{opacity:.9}92%{opacity:.9;transform:translateX(640px) skewX(-20deg)}100%{opacity:0}}
.sp{fill:#fff;opacity:0;transform-box:fill-box;transform-origin:center;animation:sp 9s infinite}@keyframes sp{0%,84%{opacity:0;transform:scale(0)}90%{opacity:1;transform:scale(1.5)}98%,100%{opacity:0;transform:scale(0)}}
.sp2{fill:#fff;transform-box:fill-box;transform-origin:center;animation:sp2 2.6s ease-in-out infinite}@keyframes sp2{0%,100%{opacity:0;transform:scale(0)}50%{opacity:1;transform:scale(1.2)}}
.bu{fill:none;stroke:rgba(160,220,255,.7);animation:bu linear infinite}@keyframes bu{from{transform:translateY(0);opacity:0}15%{opacity:1}to{transform:translateY(-360px);opacity:0}}
.whl{transform-box:fill-box;transform-origin:center;animation:spn 1.1s linear infinite}@keyframes spn{to{transform:rotate(360deg)}}
.sw2{opacity:0;animation:sw2 5s ease-in-out infinite}@keyframes sw2{0%{opacity:0;transform:translateX(-100px) skewX(-20deg)}30%{opacity:.7}70%{opacity:.7;transform:translateX(420px) skewX(-20deg)}100%{opacity:0;transform:translateX(420px) skewX(-20deg)}}
.gm{fill:#38e07b;transform-box:fill-box;transform-origin:center;animation:sp2 2.4s ease-in-out infinite}
.mist{fill:rgba(190,235,255,.5);transform-box:fill-box;transform-origin:center;animation:ms 3s ease-out infinite}@keyframes ms{from{transform:scale(.3);opacity:.9}to{transform:scale(1.8);opacity:0}}
.swl{transform-box:fill-box;transform-origin:center;animation:spn 3s linear infinite}
