/* CINEMATIC DETAILING SCROLL SHOWCASE */
.ln{position:relative;z-index:2;border-block:1px solid var(--line);background:radial-gradient(ellipse 90% 60% at 50% 0%,rgba(255,43,56,.14),transparent 75%),linear-gradient(180deg,#02050b 0%,#050a16 50%,#02050b 100%);padding:56px 0 72px;overflow:hidden}
.ln-wrap{width:min(1240px,calc(100% - 40px));margin:0 auto}
.ln-header{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:28px;gap:20px;flex-wrap:wrap}
.ln-tagline{font:800 13px var(--fd);letter-spacing:.26em;color:var(--bl);text-transform:uppercase;display:flex;align-items:center;gap:10px}
.ln-tagline::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--bl);box-shadow:0 0 14px var(--bl)}
.ln-title{margin:6px 0 0;font:800 clamp(28px,4vw,44px) var(--fd);text-transform:uppercase;letter-spacing:.04em;color:#fff}
.ln-desc{margin:6px 0 0;color:var(--mu);font-size:15px;max-width:34em;line-height:1.5}
.ln-hud-badge{display:flex;align-items:center;gap:12px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);padding:9px 18px;border-radius:99px;font:700 13px var(--fd);letter-spacing:.14em;color:#fff}
.ln-live-dot{width:8px;height:8px;border-radius:50%;background:#38e07b;box-shadow:0 0 10px #38e07b;animation:livePulse 1.8s infinite}
@keyframes livePulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.75)}}

.cinema-box{position:relative;border-radius:24px;border:1px solid rgba(255,43,56,.35);overflow:hidden;background:#020409;box-shadow:0 26px 90px -20px rgba(0,0,0,.95),0 0 50px -15px rgba(255,43,56,.28);aspect-ratio:16/9;width:100%}
.cinema-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2;display:block}
.cinema-canvas{position:absolute;inset:0;width:100%;height:100%;z-index:1;display:block}

.cinema-overlay{position:absolute;inset:0;z-index:3;pointer-events:none;display:flex;flex-direction:column;justify-content:space-between;padding:26px 30px;background:linear-gradient(180deg,rgba(0,0,0,.75) 0%,rgba(0,0,0,0) 30%,rgba(0,0,0,0) 65%,rgba(0,0,0,.88) 100%)}
.cinema-top{display:flex;justify-content:space-between;align-items:center}
.cinema-tag{font:800 12px var(--fd);letter-spacing:.22em;color:#fff;background:rgba(0,0,0,.65);border:1px solid rgba(255,255,255,.18);padding:5px 14px;border-radius:6px;backdrop-filter:blur(8px)}
.cinema-progress-val{font:800 24px var(--fd);letter-spacing:.12em;color:var(--bl);text-shadow:0 0 20px rgba(255,43,56,.85)}

.cinema-bottom{display:flex;justify-content:space-between;align-items:flex-end;gap:20px}
.cinema-info-card{background:rgba(4,8,16,.82);border:1px solid rgba(255,255,255,.16);border-radius:18px;padding:18px 24px;backdrop-filter:blur(14px);max-width:500px}
.cinema-step-tag{font:800 12px var(--fd);letter-spacing:.24em;color:var(--bl);text-transform:uppercase}
.cinema-step-title{margin:4px 0 6px;font:800 clamp(20px,2.4vw,28px) var(--fd);letter-spacing:.06em;color:#fff;text-transform:uppercase}
.cinema-step-desc{margin:0 0 10px;font-size:13px;line-height:1.55;color:#cfe0ff}
.cinema-specs{display:flex;gap:8px;flex-wrap:wrap}
.cinema-specs span{font:700 11px var(--fd);letter-spacing:.12em;text-transform:uppercase;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:99px;padding:3px 10px;color:#d5e5ff}

.cinema-ctrls{pointer-events:auto;display:flex;align-items:center;gap:10px}
.cinema-btn{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);color:#fff;padding:10px 18px;border-radius:10px;font:700 13px var(--fd);letter-spacing:.14em;cursor:pointer;backdrop-filter:blur(10px);transition:.3s;text-transform:uppercase}
.cinema-btn:hover{background:var(--bl);border-color:var(--bl);box-shadow:0 0 18px rgba(255,43,56,.5)}

.cinema-scrub-wrap{position:relative;width:100%;height:8px;background:rgba(255,255,255,.14);border-radius:99px;margin-top:16px;cursor:pointer}
.cinema-scrub-bar{height:100%;background:linear-gradient(90deg,#ff2b38,#ff6874);border-radius:99px;position:relative}
.cinema-scrub-bar::after{content:"";position:absolute;right:-6px;top:-4px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 0 14px var(--bl)}

.stage-nav{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:20px}
.stage-tab{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:14px 18px;cursor:pointer;transition:.3s;text-align:left;position:relative;overflow:hidden}
.stage-tab:hover{border-color:rgba(255,43,56,.4);background:rgba(255,255,255,.05)}
.stage-tab.on{background:rgba(255,43,56,.12);border-color:var(--bl);box-shadow:0 0 24px -6px rgba(255,43,56,.45)}
.stage-tab .st-num{font:800 12px var(--fd);letter-spacing:.18em;color:rgba(255,255,255,.45);display:block;margin-bottom:2px}
.stage-tab.on .st-num{color:var(--bl)}
.stage-tab .st-name{font:800 17px var(--fd);letter-spacing:.08em;color:#fff;text-transform:uppercase;display:block}
.stage-tab .st-range{font:600 11px var(--fd);color:var(--mu);display:block;margin-top:2px;letter-spacing:.06em}
.stage-tab .st-fill{position:absolute;left:0;bottom:0;height:3px;background:var(--bl);transition:width .2s linear}

@media(max-width:860px){.stage-nav{grid-template-columns:repeat(2,1fr)}.stage-nav .stage-tab:last-child{grid-column:span 2}.cinema-overlay{padding:16px}.cinema-info-card{padding:14px 16px;max-width:320px}.cinema-step-desc{display:none}}
@media(max-width:560px){.stage-nav{grid-template-columns:1fr}.stage-nav .stage-tab:last-child{grid-column:span 1}.cinema-info-card{max-width:none;width:100%}.cinema-bottom{flex-direction:column;align-items:stretch;gap:12px}}
.sh{display:flex;justify-content:space-between;align-items:end;gap:26px;flex-wrap:wrap;margin-bottom:48px}.sh p{margin:14px 0 0;max-width:34em}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.cd{position:relative;display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);border-radius:24px;overflow:hidden;cursor:pointer;transition:border-color .4s,box-shadow .4s,transform .4s}
.cd:hover{border-color:var(--bl);box-shadow:0 0 60px -20px rgba(255,43,56,.7);transform:translateY(-6px)}
.cd .im{position:relative;aspect-ratio:16/10;overflow:hidden}.cd .im svg{position:absolute;inset:0;width:100%;height:100%;display:block;transition:transform 1s}.cd:hover .im svg{transform:scale(1.07)}
.cd .no{position:absolute;z-index:2;left:16px;top:14px;font:800 22px var(--fd);font-style:italic;color:#fff;background:var(--rd);padding:2px 12px;border-radius:8px}
.cd .bd{display:flex;flex-direction:column;gap:10px;flex:1;padding:20px 24px 24px}.cd h3{transition:color .3s}.cd:hover h3{color:var(--bl)}.cd p{margin:0;color:var(--mu);font-size:15px;flex:1}
.ch{display:flex;gap:8px;flex-wrap:wrap}.ch span{font:700 13px var(--fd);letter-spacing:.14em;text-transform:uppercase;border:1px solid var(--line);border-radius:99px;padding:5px 13px;color:#cfe0ff}
.arr{align-self:flex-end;width:46px;height:46px;border-radius:50%;border:1px solid var(--line);display:grid;place-items:center;background:none;cursor:pointer;font-size:18px;transition:.3s}.cd:hover .arr{background:var(--bl2);border-color:var(--bl2)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.stt{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stt div{border:1px solid var(--line);border-radius:20px;padding:24px 18px;background:var(--card)}.stt b{display:block;font:800 clamp(38px,4.4vw,60px)/1 var(--fd);font-style:italic;color:var(--bl)}.stt span{font:700 13px var(--fd);letter-spacing:.2em;text-transform:uppercase;color:var(--mu)}
.big{aspect-ratio:4/5;border-radius:28px;background:var(--i-d1) center/cover;border:1px solid var(--line);position:relative;overflow:hidden}.big::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 55%,rgba(4,8,16,.8))}
.stp{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.stp .cd{padding:26px;cursor:default}.stp .cd:hover{transform:none}.stp b{font:800 54px/1 var(--fd);font-style:italic;color:var(--bl)}.stp h3{margin:12px 0 8px}.stp p{margin:0;color:var(--mu);font-size:15px}
.gg{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.tl{position:relative;aspect-ratio:4/3;border:1px solid var(--line);border-radius:22px;overflow:hidden;background:var(--card);cursor:pointer;padding:0;display:block;width:100%;text-align:left}
.tl .im{position:absolute;inset:0;background-size:cover;background-position:center;transition:transform 1.2s}.tl:hover .im{transform:scale(1.08)}
.tl::after{content:attr(data-c);position:absolute;left:14px;bottom:12px;font:700 14px var(--fd);letter-spacing:.14em;text-transform:uppercase;background:rgba(4,8,16,.75);padding:5px 13px;border-radius:99px;z-index:3}
.tl>svg{position:absolute;inset:0;width:100%;height:100%}.tl .vf{position:absolute;inset:0;border:0;border-radius:0;aspect-ratio:auto;box-shadow:none}.tl .vf .cap,.tl .vf .tag{display:none}
.lx{position:absolute;inset:0;display:grid;place-items:center;padding:10% 6% 12%;background:radial-gradient(closest-side at 50% 60%,rgba(255,43,56,.3),transparent),linear-gradient(160deg,#0c1a36,#040810)}.lx svg{width:100%;overflow:visible}
.play{position:absolute;z-index:4;right:16px;top:16px;width:48px;height:48px;border-radius:50%;background:var(--bl2);display:grid;place-items:center;box-shadow:0 8px 24px rgba(24,115,230,.6)}.play::after{content:"";border-left:14px solid #fff;border-block:9px solid transparent;margin-left:4px}
.fl2{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:30px}.fl2 button{min-height:46px;padding:0 26px;border-radius:99px;border:1px solid var(--line);background:none;font:700 17px var(--fd);letter-spacing:.1em;text-transform:uppercase;cursor:pointer}.fl2 button.on{background:var(--bl2);border-color:var(--bl2)}
.md{position:fixed;inset:0;z-index:95;background:rgba(2,5,12,.94);display:grid;place-items:center;padding:20px}.md .in2{width:min(1000px,100%);position:relative}.md .pic{aspect-ratio:4/3;max-height:78vh;width:100%;background-size:contain;background-position:center;background-repeat:no-repeat}.md .bx{position:relative;aspect-ratio:16/10;border-radius:24px;overflow:hidden;border:1px solid var(--line)}.md button.x{position:absolute;top:-54px;right:0;width:44px;height:44px;border-radius:50%;border:1px solid var(--line);background:none;cursor:pointer;font-size:20px}.md .cp{text-align:center;margin-top:12px;color:var(--mu)}
.cta{border:1px solid rgba(255,43,56,.4);border-radius:32px;padding:clamp(34px,6vw,80px);background:radial-gradient(700px 320px at 15% 0,rgba(255,43,56,.25),transparent 70%),var(--card);overflow:hidden;position:relative}.cta>*{position:relative}.cta .cc{position:absolute;right:-60px;bottom:-30px;width:min(620px,70%);opacity:.3;pointer-events:none}.cta .cc svg{width:100%}
.info{display:grid;gap:22px}.it{display:flex;gap:18px}.it svg{width:26px;flex:none;stroke:var(--bl);fill:none;stroke-width:1.8;margin-top:3px}.it small{display:block;font:700 13px var(--fd);letter-spacing:.26em;color:var(--mu);text-transform:uppercase}.it span,.it a{font-size:18px}
form{display:grid;gap:14px;background:var(--card);border:1px solid rgba(255,43,56,.5);border-radius:26px;padding:clamp(22px,4vw,38px)}form h3{font-size:34px;margin-bottom:6px}
input,select,textarea{width:100%;min-height:56px;padding:16px 20px;border-radius:16px;border:1px solid var(--line);background:#050b18;color:#fff;font:inherit;font-size:16px}textarea{min-height:110px;resize:vertical}select option{color:#000}
.map{position:relative;border:1px solid var(--line);border-radius:26px;overflow:hidden;background:#07102a;aspect-ratio:21/9;min-height:340px}.map>svg,.map iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.mp{font:600 13px Inter;fill:#fff}
.mi{position:absolute;z-index:3;left:16px;top:16px;max-width:330px;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:18px 20px}.mi b{display:block;font:800 24px var(--fd);font-style:italic;text-transform:uppercase}.mi p{margin:4px 0 12px;color:var(--mu);font-size:14px}.mi .row{gap:8px}
.pin{animation:pn 2s ease-out infinite;transform-box:fill-box;transform-origin:center}@keyframes pn{from{transform:scale(.4);opacity:.9}to{transform:scale(2.4);opacity:0}}
.rt{stroke-dasharray:6 8;animation:rd2 1s linear infinite}@keyframes rd2{to{stroke-dashoffset:-14}}
.skl{position:absolute;inset:0;overflow:hidden;pointer-events:none}.fs{position:absolute;max-width:38vw;animation:fy 8s ease-in-out infinite alternate}@keyframes fy{to{transform:translateY(-18px)}}.fs svg{display:block;width:100%;height:auto;overflow:visible}
.d{fill:none;stroke:rgba(37,180,240,.4);stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:1;animation:dw 10s ease-in-out infinite;animation-delay:inherit}.fs:nth-child(even) .d{stroke:rgba(240,82,74,.4)}@keyframes dw{0%{stroke-dashoffset:1}35%,75%{stroke-dashoffset:0}100%{stroke-dashoffset:-1}}
.ft{position:relative;z-index:1;border-top:1px solid var(--line);padding:70px 0 30px;margin-top:40px;background:rgba(2,5,12,.6)}.ft .gr{display:grid;grid-template-columns:1.4fr 1fr 1.2fr;gap:40px}.ft img{height:74px;width:auto;margin-bottom:16px}.ft h4{font:700 15px var(--fd);letter-spacing:.26em;text-transform:uppercase;color:var(--bl);margin:0 0 14px}.ft button,.ft a{display:block;background:none;border:0;padding:6px 0;color:#e2e9f7;cursor:pointer;text-align:left;font:400 16px Inter}.ft button:hover,.ft a:hover{color:var(--bl)}.ft .cp{margin-top:50px;padding-top:22px;border-top:1px solid var(--line);color:var(--mu);font:700 14px var(--fd);letter-spacing:.16em;text-transform:uppercase}
.wa{position:fixed;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:70;width:60px;height:60px;border-radius:50%;background:#25d366;display:grid;place-items:center;box-shadow:0 10px 30px rgba(37,211,102,.5);animation:wp 2.6s infinite}.wa svg{width:32px;fill:#fff}@keyframes wp{0%{box-shadow:0 0 0 0 rgba(37,211,102,.55)}70%,100%{box-shadow:0 0 0 20px rgba(37,211,102,0)}}
.up{position:fixed;right:20px;bottom:calc(92px + env(safe-area-inset-bottom,0px));z-index:70;width:52px;height:52px;border-radius:50%;border:1px solid var(--line);background:rgba(8,14,28,.92);cursor:pointer;font-size:20px;opacity:0;pointer-events:none;transition:opacity .3s}.up.s{opacity:1;pointer-events:auto}
.ph{position:absolute;inset:0;background-size:cover;background-position:center;transition:transform 1s}.cd:hover .ph{transform:scale(1.07)}.hshade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(4,8,16,.12),rgba(4,8,16,.72)),radial-gradient(closest-side,rgba(255,43,56,.16),transparent)}.stg{max-width:960px;margin:auto}.stgv{position:relative;aspect-ratio:16/9;border-radius:26px;overflow:hidden;border:1px solid var(--line);background:#030814}.stgv::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 40%,rgba(4,8,16,.85));z-index:1}.stgi{position:absolute;inset:0;background-size:cover;background-position:center;opacity:0;transform:scale(1.06);transition:opacity 1.1s ease,transform 3.2s ease}.stgi.on{opacity:1;transform:scale(1)}.stgl{position:absolute;left:22px;bottom:52px;z-index:2;font:800 clamp(26px,4vw,44px)/1 var(--fd);font-style:italic;text-transform:uppercase;text-shadow:0 2px 20px rgba(0,0,0,.6)}.stgd{position:absolute;left:22px;bottom:20px;z-index:2;display:flex;gap:8px}.stgd i{width:26px;height:4px;border-radius:4px;background:rgba(255,255,255,.3)}.stgd i.on{background:var(--bl)}@media(max-width:1000px){.nin{display:grid;grid-template-columns:1fr auto;grid-template-areas:"lg ac" "tb tb";min-height:0;gap:4px 12px;padding:8px 0 4px}.lg img{height:40px}.lg{grid-area:lg}.tabs{grid-area:tb}.ac{grid-area:ac}.tabs{justify-content:flex-start;margin:0 -4px}.tabs button{padding:0 16px;font-size:16px}.tabs button.on::after{left:16px;right:16px}.ac .b{display:none}.ac .b.sm{display:inline-flex}
.pg{padding-top:128px}.hero{grid-template-columns:1fr;min-height:0;padding-top:30px}.hv{margin-top:24px}.g3,.gg{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr;gap:34px}.stp{grid-template-columns:1fr 1fr}.sec{padding:66px 0}.ft .gr{grid-template-columns:1fr 1fr}.map{aspect-ratio:4/3}.ln svg{width:240px}}
@media(max-width:640px){.g3,.gg,.stp,.ft .gr{grid-template-columns:1fr}.hero .row .b,.cta .row .b{width:100%}.stt{gap:10px}.stt div{padding:16px 10px}.map{aspect-ratio:auto;min-height:560px}.mi{position:relative;left:0;top:0;max-width:none;margin:12px}.map>svg{top:170px;height:calc(100% - 170px)}.sh{margin-bottom:32px}.hs{gap:22px}.cta .cc{opacity:.15}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.rv{opacity:1;transform:none}.d{stroke-dashoffset:0}}

/* Hero section inspired by reference design */
.hsec{position:relative;overflow:hidden;padding:24px 0 0;background:radial-gradient(circle at 68% 65%,rgba(255,43,56,.14) 0%,rgba(11,12,16,.96) 62%,var(--bg) 100%)}
.hero-watermark{position:absolute;left:52%;top:38%;transform:translate(-50%,-50%);font-family:var(--fd);font-size:clamp(130px,25vw,340px);font-weight:900;letter-spacing:.08em;color:rgba(255,255,255,.025);pointer-events:none;user-select:none;white-space:nowrap;line-height:1;z-index:0}
.hero.filllo-hero{display:block;min-height:auto;padding:16px 0 0;position:relative;z-index:1}
.hero-top-row{display:grid;grid-template-columns:1.15fr 1fr;gap:40px;align-items:flex-start;position:relative;z-index:2}
.hero-title{font-family:var(--fd),Inter,sans-serif;font-size:clamp(54px,7.5vw,102px);font-weight:900;line-height:.96;letter-spacing:-.01em;text-transform:capitalize;margin:0 0 16px;color:#fff}
.hero-title .bl{color:var(--bl);text-shadow:0 0 35px rgba(255,43,56,.45)}
.hero-tagline{font-size:14px;letter-spacing:.16em;text-transform:uppercase;color:var(--mu);font-weight:600;margin:0}
.hero-right-col{padding-top:16px;max-width:480px;margin-left:auto}
.hero-right-col .hero-lead{font-size:clamp(15px,1.35vw,18px);line-height:1.65;color:#d1d5db;margin:0 0 24px}
.hero-cta-group{display:flex;align-items:center;gap:20px;flex-wrap:wrap}
.hero-wash-link{display:inline-flex;align-items:center;gap:10px;background:transparent;border:none;color:var(--bl);font-family:Inter,system-ui,sans-serif;font-size:clamp(17px,1.5vw,20px);font-weight:700;cursor:pointer;padding:8px 0;transition:all .25s ease}
.hero-wash-link:hover{color:#ff5c67;transform:translateX(4px)}
.hero-wash-arrow{display:inline-block;font-size:1.2em;transition:transform .25s ease}
.hero-wash-link:hover .hero-wash-arrow{transform:translateX(6px)}
.hero-wa-btn{padding:10px 20px;font-size:15px}
.hero-stats{margin-top:28px}
.hero-car-showcase{position:relative;width:100%;max-width:1120px;margin:24px auto 0;display:flex;justify-content:center;align-items:flex-end;z-index:1}
.hero-car-glow{position:absolute;right:6%;bottom:10%;width:70%;height:58%;background:radial-gradient(ellipse closest-side,rgba(255,255,255,.28),transparent 75%);pointer-events:none;filter:blur(40px)}
.hero-car-img{width:min(920px,88vw);height:auto;display:block;position:relative;z-index:2;filter:drop-shadow(0 25px 35px rgba(255,255,255,.28)) drop-shadow(0 0 25px rgba(255,255,255,.28));animation:carFloat 6s ease-in-out infinite alternate}
@keyframes carFloat{0%{transform:translateY(0px)}100%{transform:translateY(-8px)}}
@media (max-width:900px){
.hero-top-row{grid-template-columns:1fr;gap:24px}
.hero-right-col{margin-left:0;padding-top:0;max-width:100%}
.hero-car-showcase{margin-top:20px;margin-bottom:0;justify-content:center}
.hero-car-img{width:100%}
}


/* Keep the home hero at a true 16:9 ratio across screen sizes. */
.hsec{box-sizing:border-box;aspect-ratio:16/9;min-height:0;padding:clamp(8px,1.5vw,24px) 0 0;display:grid}
.hero.filllo-hero{grid-area:1/1;box-sizing:border-box;height:auto;min-height:0;padding:clamp(4px,1vw,16px) 0 0;display:flex;flex-direction:column}
.hero-top-row{flex:0 0 auto}
.hero-car-showcase{flex:1 1 0;min-height:0;margin:8px auto 0;overflow:hidden}
.hero-car-img{width:auto;height:100%;max-width:100%;object-fit:contain}
@media(max-width:900px){
  .hsec{padding:8px 0 0}
  .hero.filllo-hero{padding-top:4px}
  .hero-top-row{grid-template-columns:1.05fr 1fr;gap:12px;align-items:center}
  .hero-left-col h1{font-size:clamp(25px,7.5vw,42px);line-height:.94;margin:4px 0 6px}
  .hero-left-col .pl{font-size:clamp(8px,2vw,12px)}
  .hero-left-col .lead{font-size:clamp(9px,2.4vw,13px);line-height:1.25;margin:0}
  .hero-right-col{padding:0}
  .hero-right-col .hero-lead{font-size:clamp(9px,2vw,12px);line-height:1.3;margin-bottom:6px}
  .hero-stats{margin-top:4px}
  .hero-car-showcase{margin-top:4px}
  .hero-car-img{width:auto;height:100%;max-width:100%}
}


/* Layer the car into the hero backdrop and anchor the visible vehicle at bottom-right. */
.hero.filllo-hero{isolation:isolate}
.hero-top-row{z-index:2}
.hero-car-showcase{position:absolute;inset:0;z-index:1;width:auto;max-width:none;margin:0;overflow:hidden;pointer-events:none}
.hero-car-glow{display:none}
.hero-car-img{position:absolute;right:-33%;bottom:0;width:133%;height:auto;max-width:none;object-fit:contain;object-position:right bottom;animation:none;filter:none}
@media(max-width:900px){
  .hero-car-showcase{margin:0}
  .hero-car-img{right:-38%;bottom:0;width:145%;height:auto;max-width:none}
}
